# Generated by build.py from recipe.yml for recipe imap-rename-and-delete-a-folder. Do not edit.
set -e
cd "$(dirname "$0")"
awk '{printf "%s\r\n", $0}' > first.eml <<'EOF'
From: shop@example.com
To: ann@example.com
Subject: Order 1 shipped

Your first order is on its way.
EOF
awk '{printf "%s\r\n", $0}' > second.eml <<'EOF'
From: shop@example.com
To: ann@example.com
Subject: Order 2 shipped

Your second order is on its way.
EOF
surl --mail-domain example.com --mailbox "ann@example.com:annpass;folders=Old,Drafts,Keep" imap://127.0.0.1:8080/ &
sleep 1
curl -sS -u ann@example.com:annpass -T first.eml imap://127.0.0.1:8080/Old --next -sS -u ann@example.com:annpass -T second.eml imap://127.0.0.1:8080/Old --next -sS -u ann@example.com:annpass -T first.eml imap://127.0.0.1:8080/INBOX
curl -s -u ann@example.com:annpass -X "RENAME Old Archive" imap://127.0.0.1:8080/ --next -s -u ann@example.com:annpass imap://127.0.0.1:8080/
kill $(jobs -p)
